CREATE TYPE incident_severity AS ENUM\n  ('NEAR_MISS','FIRST_AID','RECORDABLE','HOSPITALIZATION','AMPUTATION','FATALITY');\nCREATE TYPE incident_status AS ENUM\n  ('REPORTED','UNDER_INVESTIGATION','CORRECTIVE_ACTIONS_OPEN','CLOSED');\nCREATE TYPE osha_recordability AS ENUM\n  ('PENDING_CLASSIFICATION','RECORDABLE','NOT_RECORDABLE_WITH_JUSTIFICATION');\n\nCREATE TABLE safety_incident (\n  tenant_id          uuid NOT NULL,\n  incident_id        uuid NOT NULL,\n  project_id         uuid NOT NULL,\n  site_id            uuid NOT NULL,\n  reported_by        uuid NOT NULL,\n  party_id           uuid,\n  severity           incident_severity NOT NULL,\n  status             incident_status NOT NULL DEFAULT 'REPORTED',\n  occurred_at        timestamptz NOT NULL,\n  reported_at        timestamptz NOT NULL,\n  description        text NOT NULL,\n  root_cause         text,\n  osha_recordability osha_recordability NOT NULL DEFAULT 'PENDING_CLASSIFICATION',\n  osha_justification text,\n  osha_form_300_id   uuid,\n  osha_form_301_id   uuid,\n  aggregate_version  bigint NOT NULL DEFAULT 1,\n  created_at         timestamptz NOT NULL DEFAULT now(),\n  updated_at         timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, incident_id),\n  CHECK (osha_recordability <> 'NOT_RECORDABLE_WITH_JUSTIFICATION'\n         OR osha_justification IS NOT NULL)\n);\n\nCREATE TABLE corrective_action (\n  tenant_id      uuid NOT NULL,\n  action_id      uuid NOT NULL,\n  incident_id    uuid NOT NULL,\n  description    text NOT NULL,\n  responsible_id uuid NOT NULL,\n  due_date       date NOT NULL,\n  completed_at   timestamptz,\n  status         varchar(20) NOT NULL,\n  PRIMARY KEY (tenant_id, action_id)\n);\n\nCREATE TABLE osha_300_log (\n  tenant_id      uuid NOT NULL,\n  log_id         uuid NOT NULL,\n  project_id     uuid NOT NULL,\n  calendar_year  int NOT NULL,\n  entries        jsonb NOT NULL,\n  retained_until date NOT NULL,\n  PRIMARY KEY (tenant_id, log_id),\n  UNIQUE (tenant_id, project_id, calendar_year)\n);\n\nCREATE TABLE osha_form_300 (\n  tenant_id   uuid NOT NULL,\n  form_id     uuid NOT NULL,\n  incident_id uuid NOT NULL,\n  payload     jsonb NOT NULL,\n  PRIMARY KEY (tenant_id, form_id)\n);\nCREATE TABLE osha_form_301 (\n  tenant_id   uuid NOT NULL,\n  form_id     uuid NOT NULL,\n  incident_id uuid NOT NULL,\n  payload     jsonb NOT NULL,\n  PRIMARY KEY (tenant_id, form_id)\n);\n\nCREATE TABLE notification_outbox (\n  tenant_id       uuid NOT NULL,\n  notification_id uuid NOT NULL,\n  recipient_role  varchar(60) NOT NULL,\n  subject         varchar(200) NOT NULL,\n  body            text NOT NULL,\n  created_at      timestamptz NOT NULL DEFAULT now(),\n  sent_at         timestamptz,\n  PRIMARY KEY (tenant_id, notification_id)\n);\n\nALTER TABLE safety_incident   ENABLE ROW LEVEL SECURITY;\nALTER TABLE corrective_action ENABLE ROW LEVEL SECURITY;\nALTER TABLE osha_300_log      ENABLE ROW LEVEL SECURITY;\nALTER TABLE osha_form_300     ENABLE ROW LEVEL SECURITY;\nALTER TABLE osha_form_301     ENABLE ROW LEVEL SECURITY;\nALTER TABLE notification_outbox ENABLE ROW LEVEL SECURITY;\n\nDO $$\nDECLARE t text;\nBEGIN\n  FOR t IN SELECT unnest(ARRAY[\n    'safety_incident','corrective_action','osha_300_log',\n    'osha_form_300','osha_form_301','notification_outbox'\n  ]) LOOP\n    EXECUTE format('CREATE POLICY ti_%I ON %I USING (tenant_id = current_setting(''app.tenant_id'')::uuid)', t, t);\n  END LOOP;\nEND $$;